//! Freeze for the generated `TileObjectData` registry (`tileobject/registry.rs`,
//! S1-F-7 wave A).
//!
//! `crates/tr-core/src/tileobject/registry.rs` is generated by
//! `tools/GenTileObjectData/gen.py`, which INTERPRETS `TileObjectData.Initialize`
//! (`TileObjectData.cs:2110-5014`) statement-by-statement — the copy-on-write
//! builder chain — and emits all 389 registered tiles (578 defs incl.
//! alternates/sub-tiles) plus the `Main.tileFrameImportant` and
//! `KillTile_GetItemDrops` empty-group tables. A hand-edit or a lossy merge
//! could silently change placement behaviour away from the C#.
//!
//! This test pins a fingerprint of every generated, non-comment line and checks
//! the table's shape. The other half of the freeze is the generator round-trip
//! (`python tools/GenTileObjectData/gen.py --check`, run by
//! `tools/GenTileObjectData/test_gen.py`). This test is the always-on
//! `cargo test` gate for the same table.
//!
//! To re-pin after a legitimate regeneration: run
//! `python tools/GenTileObjectData/gen.py`, then replace `DATA_FNV1A64` with the
//! value the failing assertion prints.

use std::path::PathBuf;

/// FNV-1a (64-bit) over the concatenated trimmed non-comment lines, joined by
/// `\n` (the `itemdata_freeze` pattern).
const DATA_FNV1A64: u64 = 0x5e3e_6a9e_b220_61d5;
/// The registered tile count (`addTile` calls of `Initialize`, distinct kinds).
const TILES: usize = 389;
/// Total emitted defs (top-level + alternates + sub-tiles).
const DEFS: usize = 578;

#[test]
fn the_generated_tile_object_registry_is_frozen() {
    let manifest = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let path = manifest.join("src").join("tileobject").join("registry.rs");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "{} could not be read ({e}) — registry.rs is part of the tree, so its \
             absence means a merge dropped it",
            path.display()
        )
    });

    let mut defs = 0usize;
    let mut kept: Vec<&str> = Vec::new();
    for line in text.lines() {
        let t = line.trim();
        if t.is_empty() || t.starts_with("//") {
            continue;
        }
        if t.starts_with("static D_") {
            defs += 1;
        }
        kept.push(t);
    }
    let blob = kept.join("\n");

    assert_eq!(
        defs, DEFS,
        "the registry must carry {DEFS} defs (389 tiles + alternates + sub-tiles)"
    );
    assert!(
        text.contains("pub static TABLE: &[TileObjectDef] = &["),
        "the TABLE declaration is gone"
    );
    assert!(
        text.contains("pub static BY_KIND: [Option<&'static TileObjectDef>; TILE_COUNT] = ["),
        "the BY_KIND declaration is gone"
    );
    assert!(
        text.contains("pub static FRAME_IMPORTANT: [bool; TILE_COUNT] = ["),
        "the FRAME_IMPORTANT declaration is gone"
    );
    assert!(
        text.contains("pub static KILL_TILE_NO_CELL_DROP: [bool; TILE_COUNT] = ["),
        "the KILL_TILE_NO_CELL_DROP declaration is gone"
    );

    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in blob.as_bytes() {
        h ^= u64::from(*b);
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    assert_eq!(
        h, DATA_FNV1A64,
        "the generated TileObjectData registry drifted from the pinned build \
         (S1-F-7) — either regenerate it with `python tools/GenTileObjectData/gen.py` \
         (then re-pin DATA_FNV1A64) or restore the hand-edit"
    );
}

/// The per-kind lookup agrees with the table: every `TABLE` entry resolves
/// through `BY_KIND`, and the count matches the registered tile total.
#[test]
fn the_registry_lookup_covers_every_registered_tile() {
    use tr_core::tileobject::{def_for_tile, TABLE};
    assert_eq!(TABLE.len(), TILES, "the registered tile count");
    for def in TABLE {
        let resolved = def_for_tile(def.kind).expect("every TABLE kind resolves");
        assert_eq!(resolved.kind, def.kind);
        assert_eq!(resolved.width, def.width);
        assert_eq!(resolved.height, def.height);
    }
    // A handful of unregistered kinds stay absent.
    for kind in [0u16, 1, 2, 221, 380] {
        assert!(def_for_tile(kind).is_none(), "kind {kind} is not a tile object");
    }
}
